using System.Net.Http.Json;
using System.Text.Json;
using BrewNest.Contracts.Production;
using BrewNest.Web.Services;
namespace BrewNest.Web.Features.Production.Services;
internal sealed class ProductionApiClient(HttpClient http)
{
    private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);
    public Task<ProductionMenuItemReference[]> GetReferencesAsync()=>GetAsync<ProductionMenuItemReference[]>("api/production/references");public Task<ProductionCatalogItemReference[]> GetItemNamesAsync()=>GetAsync<ProductionCatalogItemReference[]>("api/production/item-names");public Task<ProductionPlanResponse[]> GetPlansAsync()=>GetAsync<ProductionPlanResponse[]>("api/production/plans");public Task<ProductionPlanResponse> GetPlanAsync(Guid id)=>GetAsync<ProductionPlanResponse>($"api/production/plans/{id}");public Task<ProductionOrderResponse[]> GetOrdersAsync(Guid? planId=null)=>GetAsync<ProductionOrderResponse[]>(planId is null?"api/production/orders":$"api/production/orders?planId={planId}");public Task<ProductionOrderResponse> GetOrderAsync(Guid id)=>GetAsync<ProductionOrderResponse>($"api/production/orders/{id}");public Task<ProductionStatusHistoryResponse[]> GetHistoryAsync(string type,Guid id)=>GetAsync<ProductionStatusHistoryResponse[]>($"api/production/status-history?type={type}&id={id}");
    public Task<ProductionPlanResponse> CreatePlanAsync(CreateProductionPlanRequest x)=>PostAsync<ProductionPlanResponse>("api/production/plans",x);public Task<ProductionPlanResponse> ReleasePlanAsync(Guid id,ChangeProductionStatusRequest x)=>PostAsync<ProductionPlanResponse>($"api/production/plans/{id}/release",x);public Task<ProductionPlanResponse> CancelPlanAsync(Guid id,ChangeProductionStatusRequest x)=>PostAsync<ProductionPlanResponse>($"api/production/plans/{id}/cancel",x);public Task<ProductionOrderResponse> ReleaseOrderAsync(Guid id,ChangeProductionStatusRequest x)=>PostAsync<ProductionOrderResponse>($"api/production/orders/{id}/release",x);public Task<ProductionOrderResponse> IssueAsync(Guid id,IssueProductionMaterialsRequest x)=>PostAsync<ProductionOrderResponse>($"api/production/orders/{id}/issue",x);public Task<ProductionOrderResponse> CompleteAsync(Guid id,ChangeProductionStatusRequest x)=>PostAsync<ProductionOrderResponse>($"api/production/orders/{id}/complete",x);public Task<ProductionOrderResponse> CancelOrderAsync(Guid id,ChangeProductionStatusRequest x)=>PostAsync<ProductionOrderResponse>($"api/production/orders/{id}/cancel",x);
    private async Task<T> GetAsync<T>(string uri){try{using var response=await http.GetAsync(uri);return await Read<T>(response);}catch(HttpRequestException e){throw new ProductionApiException("The café server is unavailable. Please check your connection and try again.",e);}}private async Task<T> PostAsync<T>(string uri,object x){try{using var response=await http.PostAsJsonAsync(uri,x,JsonOptions);return await Read<T>(response);}catch(HttpRequestException e){throw new ProductionApiException("The café server is unavailable. Please check your connection and try again.",e);}}private static async Task<T> Read<T>(HttpResponseMessage response){if(!response.IsSuccessStatusCode)throw new ProductionApiException(ApiProblemMessage.Read(await response.Content.ReadAsStringAsync(),response.StatusCode,"Production"));return await response.Content.ReadFromJsonAsync<T>(JsonOptions)??throw new ProductionApiException("The Production API returned an empty response.");}
}
internal sealed class ProductionApiException:Exception { public ProductionApiException(string message):base(message){}public ProductionApiException(string message,Exception inner):base(message,inner){} }
